style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: url("https://i.imgur.com/G679oWt.png") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  #app, .container-main, .content, .page-content, .section-content, .game-home-page {
    background: transparent !important;
  }

  .navbar, .rbx-navbar, header {
    background: rgba(0, 0, 0, 0.4) !important;
    backdrop-filter: blur(6px);
  }

  .content, .game-card, .list-item, .section, .thumbnail-span, .card-item {
    background-color: rgba(0, 0, 0, 0.25) !important;
    border: none !important;
  }

  * {
    color: #ffffff !important;
  }
}
